import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
/** Independent instruction graph comparison: original roots invert; replay copies exact roll/activation/factory/wire slices. */
public final class ShockAcceptedDelta {
 static final String P="local/lito381/server/",PC=P+"ClientSession",H=P+"NativeAcceptedShockMutation",SP=P+"BattleSpellCatalog$ShockStunSpell",A=P+"NativeAreaMaterialAction",S=P+"NativeShockPlayerAction$Scope";
 static ClassNode read(JarFile j,String name)throws Exception{var c=new ClassNode();new ClassReader(j.getInputStream(j.getJarEntry(name+".class"))).accept(c,ClassReader.SKIP_DEBUG|ClassReader.SKIP_FRAMES);return c;}
 static MethodNode method(ClassNode c,String name){return c.methods.stream().filter(m->m.name.equals(name)).findFirst().orElseThrow();}
 static AbstractInsnNode before(AbstractInsnNode n){do{n=n.getPrevious();}while(n!=null&&n.getOpcode()<0);return n;}
 static AbstractInsnNode after(AbstractInsnNode n){do{n=n.getNext();}while(n!=null&&n.getOpcode()<0);return n;}
 static byte[] body(ClassNode c,MethodNode m,String name){var t=new ClassNode();t.version=c.version;t.access=c.access;t.name=c.name;t.superName=c.superName;var copy=new MethodNode(m.access,name,m.desc,m.signature,m.exceptions.toArray(String[]::new));m.accept(copy);t.methods.add(copy);var w=new ClassWriter(ClassWriter.COMPUTE_MAXS);t.accept(w);return w.toByteArray();}
 static List<AbstractInsnNode> between(AbstractInsnNode first,AbstractInsnNode end){var out=new ArrayList<AbstractInsnNode>();for(var n=first;n!=end;n=n.getNext()){if(n==null)throw new AssertionError("invalid bounded source slice");out.add(n);}return out;}
 static MethodInsnNode invoke(MethodNode m,String owner,String name){return Arrays.stream(m.instructions.toArray()).filter(n->n instanceof MethodInsnNode v&&v.owner.equals(owner)&&v.name.equals(name)).map(n->(MethodInsnNode)n).findFirst().orElseThrow();}
 static List<AbstractInsnNode> source(MethodNode m,boolean world){var roll=invoke(m,SP,"rollStunSeconds");var activate=invoke(m,P+"BattleTimedStatus","activateShockStun");var first=(AbstractInsnNode)activate;for(int k=0;k<6;k++)first=before(first);var end=(AbstractInsnNode)activate;while(!(end instanceof VarInsnNode v&&v.getOpcode()==ISTORE&&v.var==(world?54:50)))end=end.getNext();var put=invoke(m,P+"GameHub",world?"placeClassicWorldShockStunEffect":"placeShockStunEffect");var effect=(AbstractInsnNode)put;while(!(effect instanceof VarInsnNode st&&st.getOpcode()==LSTORE&&before(effect).getOpcode()==LCONST_0))effect=effect.getPrevious();var last=(JumpInsnNode)after(after(effect));var list=new ArrayList<AbstractInsnNode>();list.addAll(between(before(before(roll)),after(roll).getNext()));if(world){list.addAll(between(first,after(activate).getNext()));var branch=(JumpInsnNode)after(after(activate));list.addAll(between(branch.label,end.getNext()));}else list.addAll(between(first,end.getNext()));list.addAll(between(before(effect),last.label));return list;}
 static List<String> signature(List<AbstractInsnNode> nodes,Map<Integer,Integer> seeds){var indices=new IdentityHashMap<AbstractInsnNode,Integer>();int index=0;for(var n:nodes)if(n.getOpcode()>=0)indices.put(n,index++);var vars=new HashMap<>(seeds);int[] next={seeds.size()};var out=new ArrayList<String>();for(var n:nodes){if(n.getOpcode()<0)continue;String v=""+n.getOpcode();if(n instanceof VarInsnNode x)v+=":"+vars.computeIfAbsent(x.var,k->next[0]++);else if(n instanceof FieldInsnNode x)v+=":"+x.owner+":"+x.name+":"+x.desc;else if(n instanceof MethodInsnNode x)v+=":"+x.owner+":"+x.name+":"+x.desc+":"+x.itf;else if(n instanceof InvokeDynamicInsnNode x)v+=":"+x.name+":"+x.desc+":"+x.bsm+":"+Arrays.deepToString(x.bsmArgs);else if(n instanceof JumpInsnNode x){var target=(AbstractInsnNode)x.label;while(target!=null&&target.getOpcode()<0)target=target.getNext();v+=":"+(target==null||!indices.containsKey(target)?"END":indices.get(target));}else if(n instanceof LdcInsnNode x)v+=":"+x.cst;else if(n instanceof IntInsnNode x)v+=":"+x.operand;else if(n instanceof TypeInsnNode x)v+=":"+x.desc;else if(n instanceof IincInsnNode||n instanceof LookupSwitchInsnNode||n instanceof TableSwitchInsnNode||n instanceof MultiANewArrayInsnNode)throw new AssertionError("unexpected source slice instruction");out.add(v);}return out;}
 static void replay(ClassNode base,ClassNode candidate,boolean world){var original=method(base,"nativeShockPlayer"+(world?"World":"Battle")+"Body");var replay=method(candidate,"nativeAcceptedShock"+(world?"World":"Battle"));var nodes=new ArrayList<>(Arrays.asList(replay.instructions.toArray()));var first=nodes.stream().filter(n->n.getOpcode()>=0).findFirst().orElseThrow();if(!(first instanceof MethodInsnNode c)||!c.owner.equals("java/lang/System")||!c.name.equals("nanoTime")||!(after(first)instanceof VarInsnNode now)||now.getOpcode()!=LSTORE)throw new AssertionError("accepted-only current clock");nodes.remove(first);nodes.remove(now);if(world){var zero=nodes.stream().filter(n->n.getOpcode()>=0).findFirst().orElseThrow();if(zero.getOpcode()!=ICONST_0||!(after(zero)instanceof VarInsnNode applied)||applied.getOpcode()!=ISTORE)throw new AssertionError("original false activation initialization");nodes.remove(zero);nodes.remove(applied);}var ret=nodes.stream().filter(n->n.getOpcode()>=0).reduce((a,b)->b).orElseThrow();if(ret.getOpcode()!=LRETURN||!(before(ret)instanceof VarInsnNode value)||value.getOpcode()!=LLOAD)throw new AssertionError("effect identity return");nodes.remove(ret);nodes.remove(value);var expected=source(original,world);Map<Integer,Integer> left=new HashMap<>(),right=new HashMap<>();int[] old=world?new int[]{0,2,3,11,6,7,18,19}:new int[]{0,2,3,5,11,12,46};for(int i=0;i<old.length;i++){left.put(old[i],i);right.put(i,i);}var a=signature(expected,left);var b=signature(nodes,right);if(!a.equals(b)){int at=0;while(at<Math.min(a.size(),b.size())&&a.get(at).equals(b.get(at)))at++;throw new AssertionError("original activation/effect opcode graph "+world+" at="+at+" expected="+(at<a.size()?a.get(at):"END")+" actual="+(at<b.size()?b.get(at):"END"));}}
 static void inversePlan(MethodNode m,boolean world){int count=0;for(var n:m.instructions.toArray())if(n instanceof MethodInsnNode call&&call.owner.equals(H)&&call.name.equals("plan")){var loads=new ArrayList<AbstractInsnNode>();var cursor=(AbstractInsnNode)n;for(int k=0;k<5;k++){cursor=before(cursor);loads.add(cursor);}Collections.reverse(loads);int[] vars={0,2,3,world?11:5,46};for(int k=0;k<5;k++)if(world&&k==4?loads.get(k).getOpcode()!=ACONST_NULL:!(loads.get(k)instanceof VarInsnNode v)||v.getOpcode()!=ALOAD||v.var!=vars[k])throw new AssertionError("exact source plan operands");var jump=after(n);if(!(jump instanceof JumpInsnNode b)||b.getOpcode()!=IFNE||after(b.label).getOpcode()!=LCONST_0)throw new AssertionError("plan only skips to original false-applied effect gate");for(var load:loads)m.instructions.remove(load);m.instructions.remove(jump);m.instructions.remove(n);count++;}if(count!=1)throw new AssertionError("one accepted plan per PC root");}
 public static void main(String[]args)throws Exception{try(var base=new JarFile(args[0]);var jar=new JarFile(args[1])){var names=new HashSet<String>();var changes=new HashSet<String>();for(var e:Collections.list(base.entries())){names.add(e.getName());var other=jar.getJarEntry(e.getName());if(other==null)throw new AssertionError("removed entry");if(!Arrays.equals(base.getInputStream(e).readAllBytes(),jar.getInputStream(other).readAllBytes()))changes.add(e.getName());}var fresh=new HashSet<String>();for(var e:Collections.list(jar.entries()))if(!names.contains(e.getName()))fresh.add(e.getName());if(!changes.equals(Set.of(PC+".class",S+".class",A+".class",P+"NativeAcceptedHpCompletion.class"))||!fresh.equals(Set.of(H+".class",H+"$Plan.class",H+"$Output.class")))throw new AssertionError("archive boundary");
 for(var name:List.of(PC,S,A,P+"NativeAcceptedHpCompletion")){var a=read(base,name);var b=read(jar,name);if(b.fields.size()!=a.fields.size()+(name.equals(S)?1:0)||b.methods.size()!=a.methods.size()+(name.equals(PC)?2:name.equals(A)?1:0))throw new AssertionError("schema boundary");for(int k=0;k<a.fields.size();k++){var f=a.fields.get(k);var g=b.fields.get(k);if(!f.name.equals(g.name)||!f.desc.equals(g.desc)||f.access!=g.access||!Objects.equals(f.value,g.value))throw new AssertionError("original field");}if(name.equals(S)){var f=b.fields.get(b.fields.size()-1);if(!f.name.equals("nativeAcceptedShockPlan")||!f.desc.equals("Ljava/lang/Object;")||f.access!=0)throw new AssertionError("per-event scope field");}
  if(name.equals(PC))for(boolean world:new boolean[]{false,true})replay(a,b,world);
  for(var original:a.methods){String retained=name.equals(A)&&original.name.equals("captureOutput")?"nativeAcceptedShockOriginalCaptureOutput":original.name;var m=b.methods.stream().filter(v->v.name.equals(retained)&&v.desc.equals(original.desc)).findFirst().orElseThrow();if(name.equals(PC)&&original.name.matches("nativeShockPlayer(Battle|World)Body"))inversePlan(m,original.name.contains("World"));if(name.endsWith("NativeAcceptedHpCompletion")&&m.name.equals("run")){int count=0;for(var n:m.instructions)if(n instanceof MethodInsnNode c&&c.owner.equals(H)&&c.name.equals("completed")){c.owner=P+"NativeShockPlayerAction";count++;}if(count!=1)throw new AssertionError("completion handoff only");}if(!Arrays.equals(body(a,original,original.name),body(b,m,original.name)))throw new AssertionError("original body changed "+name+"."+original.name);}
 }
 for(var name:List.of(H,H+"$Plan",H+"$Output")){var c=read(jar,name);for(var f:c.fields)if((f.access&ACC_STATIC)!=0&&(!f.desc.equals("Ljava/lang/String;")||f.value==null))throw new AssertionError("static state");for(var m:c.methods)for(var n:m.instructions){if(n instanceof TypeInsnNode t&&t.getOpcode()==NEW&&(t.desc.contains("Thread")||t.desc.contains("Map")||t.desc.contains("ClassicWorldMonster")||t.desc.contains("Executor")))throw new AssertionError("registry/worker/physical projection");if(n instanceof MethodInsnNode call&&(call.owner.startsWith("java/sql/")||call.owner.startsWith("java/nio/file/")||call.owner.contains("GameStateStore")||call.owner.contains("Executor")))throw new AssertionError("unexpected IO");}}
 }System.out.println("PASS independent inverse and exact original PC roll/activation/effect/factory/packet instruction graphs; only accepted timing ports and bounded event plan added");}
}
